// Parseo del payload entrante de WhatsApp Cloud API
const body = $input.first().json.body || $input.first().json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];

// Si no es un mensaje de texto (es status, imagen, etc.) detenemos el flujo
if (!message || message.type !== 'text') {
  return [];
}

// 'session' es el identificador unico del cliente (string/alfanumerico).
// WhatsApp -> message.from (telefono). Facebook (futuro) -> seria el PSID.
const session = String(message.from);
const telefono = String(message.from);
const texto = message.text.body;
const nombrePerfil = value?.contacts?.[0]?.profile?.name || '';
const phoneNumberId = value?.metadata?.phone_number_id || '';

return [{
  json: { session, telefono, texto, nombrePerfil, phoneNumberId }
}];

