// Construye el contexto para el AI Agent: catalogo + estado de sesion + mensaje
const msg = $('Extraer Mensaje').first().json;
const session = String(msg.session);

// Catalogo (cache en PostgreSQL, incluye el identificador unico de cada producto)
const inv = $('Leer Inventario').all().map(i => i.json).filter(r => r.producto);
const catalogo = inv.map(r => `- [${r.id}] ${r.producto} | $${r.valor} | ${r.descripcion || ''}`).join('\n');

// Sesion actual del cliente (desde PostgreSQL, ya filtrada por session)
const sesionRows = $('Leer Sesiones').all().map(i => i.json);
const sesion = sesionRows[0] || {};

const estado = {
  etapa: sesion.etapa || 'inicio',
  producto_id: sesion.producto_id || '',
  producto_seleccionado: sesion.producto_seleccionado || '',
  valor: sesion.valor || '',
  nombre: sesion.nombre || '',
  direccion: sesion.direccion || ''
};

const prompt = `CATALOGO DISPONIBLE (formato: [id] producto | precio | descripcion):\n${catalogo || '(catalogo vacio)'}\n\nESTADO ACTUAL DE LA CONVERSACION:\n${JSON.stringify(estado)}\n\nMENSAJE NUEVO DEL CLIENTE:\n"${msg.texto}"`;

return [{
  json: {
    session,
    telefono: msg.telefono,
    phoneNumberId: msg.phoneNumberId,
    prompt,
    ...estado
  }
}];

// Aplana la salida del AI Agent, maneja pedido_id y el envio de imagenes
const ai = $json.output || $json;
const ctx = $('Construir Contexto').first().json;
const sesionPrev = ($('Leer Sesiones').first() && $('Leer Sesiones').first().json) || {};
const prevPedidoId = sesionPrev.ultimo_pedido_id || '';

const respuesta = ai.respuesta || 'Disculpa, no entendi. ¿Puedes repetirlo?';
const session = ctx.session;
const accion = ['crear', 'cancelar'].includes(ai.accion_pedido) ? ai.accion_pedido : 'ninguna';

// pedido_id unico (string) para un pedido NUEVO
const nuevoPedidoId = 'PED-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
const ultimoPedidoId = accion === 'crear' ? nuevoPedidoId : prevPedidoId;

// ---- Manejo de IMAGENES ----
const enviarImagen = ai.enviar_imagen === true;
const prodId = ai.producto_id || sesionPrev.producto_id || '';
const invRows = $('Leer Inventario').all().map(i => i.json);
const prod = invRows.find(r => String(r.id) === String(prodId));
let imagenes = [];
if (prod && prod.imagenes) {
  imagenes = String(prod.imagenes).split(/[\n,|]+/).map(s => s.trim()).filter(Boolean);
}
const prodNombre = (prod && prod.producto) || ai.producto_seleccionado || 'el producto';

// indice de la proxima imagen a enviar para este producto
const prevImgProd = sesionPrev.img_producto_id || '';
let imgIndex = Number(sesionPrev.img_index || 0);
if (String(prevImgProd) !== String(prodId)) imgIndex = 0; // cambio de producto -> reiniciar contador

let imgProductoId = prevImgProd;
let nuevoImgIndex = imgIndex;
let imagenUrl = '';
let hayImagen = false;
if (enviarImagen) {
  imgProductoId = prodId;
  if (imagenes.length > 0 && imgIndex < imagenes.length) {
    imagenUrl = imagenes[imgIndex];
    hayImagen = true;
    nuevoImgIndex = imgIndex + 1; // marcamos esta imagen como ya enviada
  }
}

// ---- Construir el mensaje saliente de WhatsApp ----
let wa_payload;
if (enviarImagen && hayImagen) {
  wa_payload = { messaging_product: 'whatsapp', to: ctx.telefono, type: 'image', image: { link: imagenUrl, caption: respuesta } };
} else if (enviarImagen && !hayImagen) {
  const sinMas = imagenes.length === 0
    ? `Por ahora no tengo imagenes de *${prodNombre}* para mostrarte 😊`
    : `Ya te compartí todas las imagenes disponibles de *${prodNombre}* 😊`;
  wa_payload = { messaging_product: 'whatsapp', to: ctx.telefono, type: 'text', text: { body: sinMas } };
} else {
  wa_payload = { messaging_product: 'whatsapp', to: ctx.telefono, type: 'text', text: { body: respuesta } };
}

return [{
  json: {
    session,
    telefono: ctx.telefono,
    phoneNumberId: ctx.phoneNumberId,
    etapa: ai.etapa || 'inicio',
    producto_id: ai.producto_id || '',
    producto_seleccionado: ai.producto_seleccionado || '',
    valor: (ai.valor === undefined || ai.valor === null) ? '' : ai.valor,
    nombre: ai.nombre || '',
    direccion: ai.direccion || '',
    respuesta,
    accion_pedido: accion,
    limpiar_sesion: ai.limpiar_sesion === true,
    fecha: new Date().toISOString(),
    pedido_id_crear: nuevoPedidoId,
    pedido_id_cancelar: prevPedidoId,
    ultimo_pedido_id: ultimoPedidoId,
    img_producto_id: imgProductoId,
    img_index: nuevoImgIndex,
    wa_payload
  }
}];
